arguments.command:
python3 - <<'EOF'
import h5py
f=h5py.File('/app/data/sub-m11/sub-m11_ses-03_behavior+ophys.nwb','r')
def show(name,obj):
    if isinstance(obj,h5py.Dataset):
        print(f"D {name} shape={obj.shape} dtype={obj.dtype}")
    else:
        print(f"G {name}")
f.visititems(show)
EOF

